const TZ = 'Asia/Seoul';
const weekdayMap = { Sun: '일', Mon: '월', Tue: '화', Wed: '수', Thu: '목', Fri: '금', Sat: '토' };

function getKSTParts(date) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, year: 'numeric', month: 'numeric', day: 'numeric', weekday: 'short'
  }).formatToParts(date).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
  return { year: Number(parts.year), month: Number(parts.month), day: Number(parts.day), weekday: weekdayMap[parts.weekday] };
}

function fmtDate(date) {
  const p = getKSTParts(date);
  return `${p.month}/${p.day}(${p.weekday})`;
}

function fmtTime(date) {
  return new Intl.DateTimeFormat('ko-KR', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: TZ }).format(date);
}

// 이번 주 월~일 범위 계산 (Asia/Seoul 기준 캘린더 날짜로 UTC 앵커를 만들어 날짜 연산)
const nowParts = getKSTParts(new Date());
const kstAnchor = new Date(Date.UTC(nowParts.year, nowParts.month - 1, nowParts.day));
const dow = kstAnchor.getUTCDay();
const monday = new Date(kstAnchor);
monday.setUTCDate(kstAnchor.getUTCDate() - ((dow + 6) % 7));
const sunday = new Date(monday);
sunday.setUTCDate(monday.getUTCDate() + 6);
const weekdayNames = ['일', '월', '화', '수', '목', '금', '토'];
const fmtAnchor = (d) => `${d.getUTCMonth() + 1}/${d.getUTCDate()}(${weekdayNames[d.getUTCDay()]})`;

const events = $input.all().map((item) => item.json);

if (events.length === 0) {
  return [{
    json: {
      slackText: `:calendar: *이번 주 일정 (${fmtAnchor(monday)} ~ ${fmtAnchor(sunday)})*\n\n등록된 일정이 없습니다.`
    }
  }];
}

const sorted = events.sort((a, b) => {
  const aStart = new Date(a.start?.dateTime || a.start?.date);
  const bStart = new Date(b.start?.dateTime || b.start?.date);
  return aStart - bStart;
});

const lines = sorted.map((ev) => {
  const isAllDay = !ev.start?.dateTime;
  const start = new Date(ev.start?.dateTime || ev.start?.date);
  const timeLabel = isAllDay ? '종일' : fmtTime(start);
  const title = ev.summary || '(제목 없음)';
  return `• ${fmtDate(start)} ${timeLabel} - ${title}`;
}).join('\n');

return [{
  json: {
    slackText: `:calendar: *이번 주 일정 (${fmtAnchor(monday)} ~ ${fmtAnchor(sunday)})*\n\n${lines}`
  }
}];
